/**
 * 获取指定产线分类与子分类标签下的产品型号列表 (支持多字段即时搜索)
 */
export function getModelsForSubcategory(
  lineName: string,
  subcategoryName: string,
  searchKey = ''
): ProductModelItem[] {
  if (!lineName) return []
  const lineSubs = PRODUCT_MODELS_DICTIONARY[lineName] || {}
  
  let models: ProductModelItem[] = []
  if (subcategoryName && subcategoryName !== '全部') {
    models = lineSubs[subcategoryName] || []
  } else {
    // 若未选具体子分类或选了“全部”，返回该产线下首个子分类或汇总型号
    const firstSub = Object.keys(lineSubs)[0]
    models = firstSub ? lineSubs[firstSub] : []
  }
  
  if (!searchKey || !searchKey.trim()) {
    return models
  }
  
  const q = searchKey.trim().toLowerCase()
  return models.filter(
    (m) =>
      m.model.toLowerCase().includes(q) ||
      m.desc.toLowerCase().includes(q) ||
      (m.code && m.code.toLowerCase().includes(q)) ||
      (m.capacity && m.capacity.toLowerCase().includes(q)) ||
      (m.voltage && m.voltage.toLowerCase().includes(q))
  )
}

/**
 * 将 ProductModelItem 转换为指标卡片与抽屉详情 (Mode B) 的标准 IndicatorMetric 格式
 */
export function convertModelToMetric(m: ProductModelItem, unitName = ''): any {
  return {
    id: m.id,
    code: m.code ? `MOD-${m.code}` : `MOD-${m.model.replace(/[^a-zA-Z0-9]/g, '-')}`,
    name: `单位产品综合能耗 (${m.model})`,
    category: 'product',
    categoryName: `三、产线子分类管控指标 · ${m.lineName} · ${m.subcategoryName}`,
    unit: m.energyUnit,
    curVal: m.energyVal,
    yoy: m.yoy,
    isYoyDown: m.isYoyDown,
    status: '常规监测',
    statusType: 'green',
    badge: m.capacity ? `${m.capacity} · ${m.voltage || ''}` : m.model,
    tipText: m.tipText,
    formula: m.formula,
    formulaDesc: m.formulaDesc,
    numeratorName: '该型号批次生产实际消耗综合能源量',
    numeratorVal: `${(parseFloat(m.energyVal) * 15).toFixed(2)} tce`,
    denominatorName: '该型号完工合格入库产量',
    denominatorVal: `15 ${m.unitSuffix}`,
    dataSource: `${unitName || '生产厂区'} ERP/MES 生产工单与数字化能源计量系统`,
    rawMeters: [
      {
        medium: '电力',
        meterCode: `EM-MOD-${m.id.slice(-4)}-01`,
        location: `${m.lineName}装配试验配电分路柜`,
        reading: m.elecVal,
        unit: 'kWh',
        coeff: '0.0001229',
        tce: (parseFloat(m.elecVal.replace(',', '')) * 0.0001229).toFixed(3),
      },
      ...(m.steamVal ? [{
        medium: '蒸汽',
        meterCode: `STM-MOD-${m.id.slice(-4)}-01`,
        location: `${m.lineName}真空干燥与固化热力总管`,
        reading: m.steamVal,
        unit: 'GJ',
        coeff: '0.0341',
        tce: (parseFloat(m.steamVal) * 0.0341).toFixed(3),
      }] : []),
    ],
    trendHistory: m.trendHistory,
  }
}
